module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one bit of data synchronously
    task drive_bit(input bit val);
        begin
            @(posedge clk);
            #1; // small offset after clock edge
            data = val;
        end
    endtask

    // Task to check expected output
    task check_output(input bit expected);
        begin
            // Wait slightly after clock edge to sample stable output
            @(posedge clk);
            #2;
            if (start_shifting !== expected) begin
                $display("Time %0t: Mismatch! data=%b, expected start_shifting=%b, got=%b", 
                         $time, data, expected, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Apply reset
        #12;
        reset = 0;

        // Check initial state after reset
        #2;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset failed! start_shifting is %b", $time, start_shifting);
            errors = errors + 1;
        end

        // Test Sequence 1: Incorrect stream (1, 0, 1, 1) -> should not trigger
        drive_bit(1); check_output(0);
        drive_bit(0); check_output(0);
        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0);

        // Test Sequence 2: Correct stream (1, 1, 0, 1) -> should trigger start_shifting = 1
        drive_bit(1); check_output(0); // '1'
        drive_bit(1); check_output(0); // '11'
        drive_bit(0); check_output(0); // '110'
        drive_bit(1); check_output(1); // '1101' -> triggers

        // Test Sequence 3: Verify it stays 1 forever, even with arbitrary data
        drive_bit(0); check_output(1);
        drive_bit(0); check_output(1);
        drive_bit(1); check_output(1);

        // Test Sequence 4: Reset behavior
        @(posedge clk);
        reset = 1;
        #2;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Synchronous reset failed to clear start_shifting!", $time);
            errors = errors + 1;
        end

        // Deassert reset and test another pattern (overlapping: 11101)
        @(posedge clk);
        reset = 0;

        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0); // second '1' in 111
        drive_bit(0); check_output(0); // '0'
        drive_bit(1); check_output(1); // '1' -> triggers via overlap

        #20;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
